// dayjs is the app's one genuine third-party dependency. It is not installed: the import map
// (generated by mport) points "dayjs" and "dayjs/plugin/relativeTime" at esm.sh, with integrity.
import dayjs from "dayjs";
import relativeTime from "dayjs/plugin/relativeTime";

dayjs.extend(relativeTime);

export const ago = (timestamp) => dayjs(timestamp).fromNow();
export const clock = (timestamp) => dayjs(timestamp).format("HH:mm:ss");

/** "Due in 3 days" / "Due 2 days ago" for a YYYY-MM-DD date; `overdue` when it is before today. */
export function dueText(iso, now = Date.now()) {
  if (!iso) return { text: "No due date", overdue: false };
  const due = dayjs(iso).endOf("day");
  return { text: `Due ${due.from(now)}`, overdue: due.valueOf() < now };
}
